<script setup lang="ts">
import{computed,onMounted,reactive,ref,watch}from'vue'
import{ElMessage,ElMessageBox}from'element-plus'
import{useAuthStore}from'../../stores/auth'
import{admitPatient,createInpatient,dischargePatient,getInpatients,getOperationDepartments,getOperationDoctors,getPatients,getWardBeds}from'../../services/operations'
import type{Department,DoctorSummary,InpatientAdmission,PatientSummary,WardBed}from'../../types/medical'
const auth=useAuthStore(),canManage=computed(()=>auth.user?.role==='admin'||auth.user?.role==='doctor'),isPatient=computed(()=>auth.user?.role==='patient'),rows=ref<InpatientAdmission[]>([]),patients=ref<PatientSummary[]>([]),doctors=ref<DoctorSummary[]>([]),departments=ref<Department[]>([]),beds=ref<WardBed[]>([]),loading=ref(false),dialog=ref(false),saving=ref(false),search=ref(''),status=ref(''),page=ref(1),total=ref(0)
const form=reactive({patient_id:undefined as number|undefined,doctor_id:undefined as number|undefined,department_id:undefined as number|undefined,bed_id:undefined as number|undefined,admission_diagnosis:''})
async function load(){loading.value=true;try{const data=await getInpatients({page:page.value,search:search.value||undefined,status:status.value||undefined});rows.value=data.results;total.value=data.count}catch(e:any){ElMessage.error(e.response?.data?.detail||'住院记录加载失败')}finally{loading.value=false}}
function searchAdmissions(){page.value=1;load()}
async function loadBeds(){form.bed_id=undefined;beds.value=[];if(!form.department_id)return;try{beds.value=(await getWardBeds({department:form.department_id,available:true})).results}catch(e:any){ElMessage.error(e.response?.data?.detail||'床位加载失败')}}
async function open(){Object.assign(form,{patient_id:undefined,doctor_id:undefined,department_id:undefined,bed_id:undefined,admission_diagnosis:''});dialog.value=true;[patients.value,doctors.value,departments.value]=await Promise.all([getPatients(),getOperationDoctors(),getOperationDepartments()])}
watch(()=>form.department_id,()=>{if(dialog.value)loadBeds()})
async function submit(){if(!form.patient_id||!form.doctor_id||!form.department_id||!form.bed_id||!form.admission_diagnosis.trim()){ElMessage.warning('请完整选择患者、医师、科室、可用床位并填写入院诊断');return}saving.value=true;try{await createInpatient(form);ElMessage.success('住院申请已创建');dialog.value=false;await load()}catch(e:any){ElMessage.error(e.response?.data?.detail||JSON.stringify(e.response?.data?.errors||'创建失败'))}finally{saving.value=false}}
async function admit(row:InpatientAdmission){try{await ElMessageBox.confirm(`确认为 ${row.patient_name} 办理入院？`,'办理入院');await admitPatient(row.id);ElMessage.success('入院办理完成');await load()}catch(e:any){if(e!=='cancel'&&e!=='close')ElMessage.error(e.response?.data?.detail||'操作失败')}}
async function discharge(row:InpatientAdmission){try{const{value}=await ElMessageBox.prompt('填写诊疗经过、出院情况和随访建议','办理出院',{inputType:'textarea',inputValidator:value=>Boolean(value.trim())||'出院小结不能为空'});await dischargePatient(row.id,value.trim());ElMessage.success('出院办理完成');await load()}catch(e:any){if(e!=='cancel'&&e!=='close')ElMessage.error(e.response?.data?.detail||'操作失败')}}
onMounted(load)
</script>
<template>
  <section>
    <div class="page-heading"><div><p class="eyebrow">INPATIENT CARE</p><h1>{{isPatient?'我的住院记录':'住院管理'}}</h1><p>覆盖住院申请、床位信息、入院与出院小结</p></div><el-button v-if="canManage" type="primary" @click="open">＋ 住院申请</el-button></div>
    <el-card class="table-card">
      <div class="table-tools"><el-input v-model="search" clearable placeholder="搜索住院号、患者或诊断" @keyup.enter="searchAdmissions"/><el-select v-model="status" clearable placeholder="全部状态" @change="searchAdmissions"><el-option label="待入院" value="pending"/><el-option label="住院中" value="admitted"/><el-option label="已出院" value="discharged"/><el-option label="已取消" value="cancelled"/></el-select><el-button @click="searchAdmissions">查询</el-button></div>
      <el-table v-loading="loading" :data="rows" empty-text="暂无住院记录"><el-table-column prop="admission_no" label="住院号" min-width="150"/><el-table-column v-if="!isPatient" prop="patient_name" label="患者"/><el-table-column prop="department_name" label="科室"/><el-table-column prop="doctor_name" label="主治医师"/><el-table-column label="床位"><template #default="{row}">{{row.ward||'待分配'}} / {{row.bed_no||'—'}}</template></el-table-column><el-table-column prop="admission_diagnosis" label="入院诊断" min-width="200" show-overflow-tooltip/><el-table-column prop="status_display" label="状态"/><el-table-column v-if="canManage" label="操作" width="150"><template #default="{row}"><el-button v-if="row.status==='pending'" link type="primary" @click="admit(row)">办理入院</el-button><el-button v-if="row.status==='admitted'" link type="success" @click="discharge(row)">办理出院</el-button></template></el-table-column></el-table>
      <div class="pagination"><span>共 {{total}} 条</span><el-pagination v-model:current-page="page" layout="prev,pager,next" :total="total" @current-change="load"/></div>
    </el-card>
    <el-dialog v-model="dialog" title="创建住院申请" width="min(650px,94vw)"><el-form label-position="top"><el-row :gutter="14"><el-col :span="12"><el-form-item label="患者" required><el-select v-model="form.patient_id" filterable style="width:100%"><el-option v-for="item in patients" :key="item.id" :label="`${item.full_name} · ${item.patient_no}`" :value="item.id"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="主治医师" required><el-select v-model="form.doctor_id" filterable style="width:100%"><el-option v-for="item in doctors" :key="item.id" :label="`${item.full_name} · ${item.title}`" :value="item.id"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="科室" required><el-select v-model="form.department_id" style="width:100%"><el-option v-for="item in departments" :key="item.id" :label="item.name" :value="item.id"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="可用床位" required><el-select v-model="form.bed_id" filterable clearable :disabled="!form.department_id" style="width:100%" placeholder="请先选择科室"><el-option v-for="bed in beds" :key="bed.id" :label="`${bed.ward_name} · ${bed.bed_no}（¥${bed.daily_rate}/日）`" :value="bed.id"/></el-select><small v-if="form.department_id&&!beds.length">该科室暂无空闲床位，请先在资源管理中添加床位。</small></el-form-item></el-col></el-row><el-form-item label="入院诊断" required><el-input v-model="form.admission_diagnosis" type="textarea" :rows="3"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="submit">提交申请</el-button></template></el-dialog>
  </section>
</template>
